        if not fmt: raise ValueError('unable to auto detect format')
    if fmt=='json': return json.loads(raw)
    if fmt=='toml':
        if tomllib: return tomllib.loads(raw)
        out={}; cur=out
        for line in raw.splitlines():
            line=line.split('#',1)[0].strip()
            if not line: continue
            if line.startswith('[') and line.endswith(']'):
                cur=out
                for bit in line[1:-1].split('.'): cur=cur.setdefault(bit,{})
            elif '=' in line:
                k,v=line.split('=',1); v=v.strip()
                try: cur[k.strip()]=json.loads(v)
                except: cur[k.strip()]=v.strip('\"\'')
        return out
    if fmt=='querystring':
        d={}
        for k,v in urllib.parse.parse_qsl(raw,keep_blank_values=True): d[k]=v
        return d
    if fmt=='ini':
        p=configparser.ConfigParser(); p.read_string(raw)
        out={'default':dict(p.defaults())}
        out.update({s:dict(p.items(s)) for s in p.sections()})
        return out
    if fmt in ('yaml','cbor'): return json.loads(raw)
    raise ValueError('unsupported format')

